def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--config-only', action='store_true')
    args = parser.parse_args()
    for directory in ['data', 'models', 'archives', 'vendor', 'results/B_full', 'results/B_wikimel', 'results/rev3', 'data/rev3_visual']:
        (ROOT / directory).mkdir(parents=True, exist_ok=True)
    for name, value in CONFIG.items():
        target = ROOT / name
        target.parent.mkdir(parents=True, exist_ok=True)
        content = json.dumps(value, indent=2)
        if target.exists():
            assert json.loads(target.read_text()) == value, name
        else:
            target.write_text(content, encoding='utf-8')
    if args.config_only:
        return
    for row in PINS:
        target = ROOT / row['path']
        if target.exists():
            assert hashlib.sha256(target.read_bytes()).hexdigest() == row['sha256'], row['path']
            continue
        response = requests.get(row['url'], timeout=120)
        response.raise_for_status()
        assert hashlib.sha256(response.content).hexdigest() == row['sha256'], row['url']
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(response.content)
        print('Verified', row['path'])
if __name__ == '__main__':
    main()
